/**
 * In-memory stand-in for ERP/PIM. In production this would call upstream APIs.
 * Sync mutates this snapshot; cached reads use the last materialized view until invalidation.
 */

const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms))

const initialItems = () => [
  {
    id: 'sku-lap-001',
    sku: 'LAP-001',
    name: 'Laptop',
    price: 999,
    stock: 42,
    available: true,
  },
  {
    id: 'sku-pho-002',
    sku: 'PHO-002',
    name: 'Phone',
    price: 699,
    stock: 128,
    available: true,
  },
  {
    id: 'sku-tab-003',
    sku: 'TAB-003',
    name: 'Tablet',
    price: 499,
    stock: 0,
    available: false,
  },
  {
    id: 'sku-hdp-004',
    sku: 'HDP-004',
    name: 'Headphones',
    price: 199,
    stock: 256,
    available: true,
  },
  {
    id: 'sku-wat-005',
    sku: 'WAT-005',
    name: 'Watch',
    price: 299,
    stock: 73,
    available: true,
  },
]

let erpState = {
  /** @type {string | null} */
  lastSyncedAt: new Date().toISOString(),
  /** @type {ReturnType<typeof initialItems>} */
  products: initialItems(),
  /** Increments on each successful pull from ERP */
  generation: 0,
}

/**
 * Full catalog snapshot (read path). Call through `getCachedCatalog` so requests stay on the cache.
 */
export async function getCatalogSnapshot() {
  await delay(100)
  return {
    syncedAt: erpState.lastSyncedAt,
    generation: erpState.generation,
    products: erpState.products.map((p) => ({ ...p })),
  }
}

/**
 * Long-running upstream sync (thousands of SKUs). Run inside `after()` so the admin UI returns immediately.
 */
export async function syncCatalogFromErp() {
  await delay(2200)
  erpState.generation += 1
  erpState.lastSyncedAt = new Date().toISOString()
  erpState.products = erpState.products.map((p) => ({
    ...p,
    price: p.price + (erpState.generation % 3 === 0 ? -5 : 5),
    stock: Math.max(0, p.stock + (erpState.generation % 2 === 0 ? 2 : -1)),
    available: p.stock + (erpState.generation % 2 === 0 ? 2 : -1) > 0,
  }))
}

